"""Standalone target-image concept review only, not the actual Unity game.
Relative references must remain with this HTML within the V11 ZIP.
"""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
items=json.loads((ROOT/'data'/'room302_interaction_manifest.json').read_text('utf-8'))['props']
props=[{'id':p['prop_id'],'zone':p['zone'],'name':p['label_ko'],'desc':p['observation_ko'],'type':p['interaction_type']} for p in items]
html=r'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TABLE//ZERO — V11 Visual Direction</title>
<style>
:root{color-scheme:dark;--ink:#080a0d;--card:rgba(11,15,19,.94);--muted:#acb1b5;--main:#eceae4;--line:rgba(255,255,255,.12);--accent:#b77d69}
*{box-sizing:border-box}body{margin:0;background:#050608;color:var(--main);font:15px/1.5 'Malgun Gothic','Apple SD Gothic Neo',system-ui,sans-serif}button,select,input{font:inherit}button{cursor:pointer;color:inherit;border:1px solid var(--line);background:#12161c}button:hover{border-color:#d8a18f}button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid #dfa18c;outline-offset:2px}
header{height:74px;display:flex;align-items:center;justify-content:space-between;padding:0 24px;border-bottom:1px solid var(--line);gap:12px;background:#080b0ef7} .brand{font-family:Arial,sans-serif;letter-spacing:.16em;font-weight:700;font-size:20px}.brand b{color:#d77b76}small{display:block;color:#8c9499;letter-spacing:0;font-size:10px}.meta{color:#a8afb4;font-size:12px;max-width:430px}.tabs{display:flex;gap:8px}.tabs button{padding:10px 16px;border-radius:6px;font-size:13px}.tabs button.active{border-color:#ac796b;background:#312022}
main{display:grid;grid-template-columns:minmax(0,1fr) 355px;gap:18px;padding:18px;max-width:1900px;margin:auto}.stage{position:relative;background:#0b0e11;border:1px solid #34383c;border-radius:12px;overflow:hidden;aspect-ratio:16/9;box-shadow:0 25px 80px #0009}.stage img{width:100%;height:100%;object-fit:cover;display:block}.vignette{pointer-events:none;position:absolute;inset:0;background:linear-gradient(0deg,rgba(0,0,0,.6),transparent 22%),linear-gradient(90deg,#0005,transparent 35%)}.caption{position:absolute;bottom:12px;left:14px;background:rgba(5,8,10,.78);border:1px solid #ffffff30;border-radius:4px;padding:8px 12px;font-size:12px}.upper{position:absolute;top:16px;left:16px;background:#070a0db8;backdrop-filter:blur(8px);padding:10px 13px;border-left:2px solid #b98573;font-size:12px}.upper strong{font-size:14px;display:block}.side{background:#0c1015;border:1px solid #30343a;border-radius:12px;padding:18px;align-self:start}.side h2{font-size:19px;font-weight:600;margin:0 0 5px}.side p{color:#adb5b7;margin:0 0 16px;font-size:12px}.hint{padding:12px 13px;background:#15191d;border-left:2px solid #bb806d;color:#d9d4cc;font-size:12px;margin-bottom:18px}.controls{display:flex;gap:7px;margin:10px 0}select,input{background:#151a20;border:1px solid #3c4247;color:#eae9e5;padding:11px;border-radius:6px;width:100%}input::placeholder{color:#7e868a}.scroll{max-height:360px;overflow:auto;display:flex;flex-direction:column;gap:6px;margin-top:12px}.item{padding:12px;text-align:left;border-radius:7px;display:flex;justify-content:space-between;gap:8px;background:#13171d}.item small{color:#a4abb0}.item.active{border-color:#b88470;background:#221b1a}.detail{margin-top:14px;border-top:1px solid var(--line);padding-top:14px;min-height:120px}.detail h3{margin:0 0 6px;font-size:15px}.detail p{font-size:13px;color:#ccc7bf;margin-bottom:6px}.note{font-size:11px;color:#92999c}.bar{height:3px;background:#32363a;margin:0 0 16px}.bar span{display:block;height:100%;background:#af7467}.foot{padding:10px 22px 25px;text-align:center;color:#8c9295;font-size:11px}
@media(max-width:1050px){main{grid-template-columns:1fr}.side{width:100%}.scroll{max-height:260px}}@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}
</style></head><body><header><div class="brand">TABLE<b>//</b>ZERO<small>V11 FINAL ART DIRECTION · REFERENCE VIEWER</small></div><nav class="tabs"><button id="showScene" class="active" type="button">302호 현장</button><button id="showInterview" type="button">심문실</button></nav><div class="meta">기존 이미지의 수준을 낮추지 않는다 · 3D 실제 실행 화면이 아닌 <b>아트 디렉션 리뷰</b></div></header>
<main><section class="stage" aria-label="승인 아트 이미지"><img id="sceneImg" src="../references_images/SCENE_302_TARGET_VISUAL.png" alt="사용자가 선택한 302호 수사 이미지"><div class="vignette"></div><div class="upper"><strong id="stageName">CASE 001 / 302호의 밤</strong><span id="stageStatus">세밀 조사 · 손과 소품 · 공간음</span></div><div class="caption" id="stageCaption">화면 참조는 이미지를 기반으로 하며 실사 3D 구현을 의미하지 않습니다</div></section>
<aside class="side"><h2 id="sideTitle">현장 소품 상세 설계</h2><p id="sideDesc">모든 실제 배치 사물에는 고유 ID·애니메이션·상태·사건 연계가 필요</p><div class="hint" id="sideHint">코드 명세에 등록된 140개 대상 중 일부를 골라 확인할 수 있습니다 · Unity에서는 실제 Mesh와 Colliders 제작 및 검증 필수</div><section id="propSelector"><div class="controls"><select id="zone"><option value="entrance">현관</option><option value="kitchen">주방</option><option value="living">거실</option><option value="sleep">침실</option><option value="bath">화장실</option><option value="hall">복도</option></select></div><input id="filter" placeholder="사물명 검색" aria-label="사물명 검색"><div class="scroll" id="items"></div></section><div class="detail"><h3 id="detailTitle">사물을 선택하세요</h3><p id="detailText">고유 프리팹·상호작용·관찰 내용은 서버 계약으로 연결합니다</p><div class="note" id="detailTag"></div></div></aside></main>
<div class="foot">시각 기준 2장과 인터랙션 명세를 확인하는 미리보기입니다 · 실제 AI 응답/Unity 애니메이션/물리 시스템은 포함하지 않습니다</div>
<script>
const props=__INJECT_PROPS__;
let mode='scene', selection=null;
const $=id=>document.getElementById(id);
function renderList(){const zone=$('zone').value;const query=$('filter').value.trim();let arr=props.filter(x=>x.zone===zone&&x.name.includes(query));$('items').innerHTML='';for(const x of arr){const b=document.createElement('button');b.className='item'+(selection===x.id?' active':'');b.innerHTML='<span></span><small></small>';b.querySelector('span').textContent=x.name;b.querySelector('small').textContent=x.type;b.onclick=()=>{selection=x.id;$('detailTitle').textContent=x.name;$('detailText').textContent=x.desc;$('detailTag').textContent=x.id+' · '+x.type+' · 실제 3D 제작/Unity 검수 필요';renderList()};$('items').appendChild(b)} if(!arr.length){$('items').textContent='이 공간에는 검색 결과가 없습니다'}}
function changeMode(next){mode=next;$('showScene').classList.toggle('active',mode==='scene');$('showInterview').classList.toggle('active',mode==='interview');if(mode==='scene'){$('sceneImg').src='../references_images/SCENE_302_TARGET_VISUAL.png';$('stageName').textContent='CASE 001 / 302호의 밤';$('stageStatus').textContent='세밀 조사 · 손과 소품 · 공간음';$('sideTitle').textContent='현장 소품 상세 설계';$('sideDesc').textContent='물건은 실제로 손에 쥐고 서랍과 욕실 내부를 조사해야 합니다';$('sideHint').textContent='140개 대상은 검수·구현 명세입니다 · 실제 모델이 완성된 건 아닙니다';$('propSelector').hidden=false;} else {$('sceneImg').src='../references_images/INTERROGATION_TARGET_VISUAL.png';$('stageName').textContent='CASE 001 / 심문';$('stageStatus').textContent='자유 질문 · 마이크 · AI 기억 · 결과';$('sideTitle').textContent='심문 화면 품질 개선';$('sideDesc').textContent='자연스러운 1대1 시선과 AI 대응이 주인공입니다';$('sideHint').textContent='추천 14초 / 자유 타이핑 24초 / 마이크 24초 · LLM/STT 지연은 차감하지 않음 · 혐조도/압박감 퍼센트는 실제 UI에서 제거';$('propSelector').hidden=true;$('detailTitle').textContent='실제 구현 기준';$('detailText').textContent='시네마 모드에서 좌우 판넬을 최소화하고, 질문 입력 완료 시 인물 연기로 시선을 되돌립니다';$('detailTag').textContent='정답 확률·혐의 퍼센트 표시 금지 · 실제 사건 기억 서버 전용'} }
$('zone').onchange=()=>{selection=null;renderList()};$('filter').oninput=()=>renderList();$('showScene').onclick=()=>changeMode('scene');$('showInterview').onclick=()=>changeMode('interview');renderList();
</script></body></html>'''
html=html.replace('__INJECT_PROPS__',json.dumps(props,ensure_ascii=False))
path=ROOT/'preview'/'V11_FINAL_ART_AND_INTERACTION_REVIEW.html'
path.write_text(html,encoding='utf-8')
print('Wrote',path)
